from pathlib import Path
p=Path('dashboard.html');s=p.read_text();s=s.replace('Your first 60 days are on us','Your first 30 days are on us').replace('$29 <small>/ month after your free trial</small>','$24.99 <small>/ month after your free trial</small>').replace('Use BaristaMatch free for 60 days. After that, continue with one simple monthly café subscription.','Use BaristaMatch free for 30 days. After that, continue for just $24.99/month.').replace('No card is collected during signup today. Secure subscription checkout will appear here once billing is activated.','No card is required for your 30-day trial. After the trial, continue for $24.99/month. Cancel anytime.')
p.write_text(s)
p=Path('terms.html');s=p.read_text();needle='<h2>8. Ending use</h2>';billing='<h2>8. Café free trial and subscriptions</h2><p>Barista accounts are free. Eligible café accounts receive a 30-day free trial with no credit card required to start. After the trial, continued access to paid café hiring features is offered at $24.99 per month per café location unless a different offer is clearly presented before purchase. Paid subscriptions renew monthly until canceled. You may cancel future renewal at any time; cancellation takes effect at the end of the then-current paid billing period. Except where required by law or expressly stated otherwise, fees already charged for a billing period are not refundable. Ending a trial or subscription does not automatically delete your account or existing profile data.</p>\n<h2>9. Ending use</h2>'
if needle in s:s=s.replace(needle,billing,1).replace('<h2>9. Changes to these terms</h2>','<h2>10. Changes to these terms</h2>').replace('<h2>10. Contact</h2>','<h2>11. Contact</h2>')
p.write_text(s)
